var n=`1232-arroz-con-leche-cubano`;var a=`world-1232`;var r=`CU`;var t=`central-america-caribbean`;var o=4;var s=99;var c={en:`Arroz con Leche Cubano`,ua:`Кубинський рисовий пудинг`};var d={en:`Arroz con Leche Cubano is a dish from Cuba featuring white rice, whole cow milk, sweetened condensed milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Кубинський рисовий пудинг, страва кухні країни Куба з такими основними складниками: білий рис, цільне коров'яче молоко, згущене молоко з цукром. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 34 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 34 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:34,i:[[`white-rice`,340,`g`],[`whole-cow-milk`,880,`ml`],[`water`,350,`ml`],[`cassia-cinnamon`,2,`pcs`]]},{en:`Simmer the liquid and flavorings uncovered for about 13 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 13 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:13,i:[[`sweetened-condensed-milk`,200,`g`],[`white-granulated-sugar`,65,`g`],[`vanilla-extract`,5,`ml`]]},{en:`Refrigerate the prepared mixture for about 50 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 50 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:50,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ground-cinnamon`,3,`g`]]}];var l={slug:n,id:a,country:`CU`,region:t,servings:4,minutes:99,title:c,text:d,steps:u};export{r as country,l as default,a as id,s as minutes,t as region,o as servings,n as slug,u as steps,d as text,c as title};